combinedSchema.method('toObject', function () {
  const obj = this.getCleanBase();
  obj.additionalFields = this.additionalFields;
  return obj;
});

combinedSchema.getCleanBase = function () {
  const clean = this.getCleanBase();
  delete clean.__v;
  return clean;
};

export const CombinedModel = mongoose.model('CombinedModel', combinedSchema);
```

4. In the `toObject` method of the combined schema, combine the two objects and remove any unnecessary properties (in this case, `__v`) from the base object before returning it.

