```javascript
const https = require('https');
const axios = require('axios');
const type = require('./utils/projects-utils/src/types');

export interface CronTriggerInvokeEvent {
    ownerId: string;
    deploymentId: string;
    projectId: string;
    cron: type.CronJobDefinition;
    url: string;
}

export const handler: Handler = async (event, context) => {
    const timestampInMs = Date.now();
    const { ownerId, deploymentId, projectId, cron, url } = event;

    try {
        const response = await axios.get(url, {
            headers: {
                'User-Agent': 'vercel-cron/1.0',
            },
        });
        const data = response.data;
        const statusCode = response.status;

        // The following invocation response payload will be forwarded to Tinybird for usage tracking
        return {
            ownerId,
            deploymentId,
            projectId,
            path: cron.path,
            schedule: cron.schedule,
            host: cron.host,
            timestampInMs,
            awsRequestId: context.awsRequestId,
            statusCode,
            data,
        };
    } catch (error) {
        console.error(`Error making HTTP request: ${error}`);
        throw error;
    }
};
```

