let statement1 = Statement(helpfulness: 75, verbosity: 6)
let statement2 = Statement(helpfulness: 85, verbosity: 5)
let statement3 = Statement(helpfulness: 90, verbosity: 3)

// Calculate the total weighted rating
func calculateWeightedRating(_ statement: Statement) -> Double {
    let weightedHelpfulness = Double(statement.helpfulness) / 100
    let weightedVerbosity = Double(statement.verbosity) / 9
    return weightedHelpfulness + weightedVerbosity
}

