Here's an outline of how you could create a generic REST service wrapper class with authentication token handling in C#:

1. Define the base class `RestServiceWrapper` which will be inherited by all specific services:

```csharp
public abstract class RestServiceWrapper
{
    protected string BaseUrl { get; set; }
    protected string AccessToken { get; set; }

    protected HttpClient HttpClient { get; }

    protected RestServiceWrapper(string baseUrl, string accessToken)
    {
        BaseUrl = baseUrl;
        AccessToken = accessToken;

        HttpClient = new HttpClient()
        {
            BaseAddress = new Uri(BaseUrl),
            Timeout = TimeSpan.FromSeconds(30) // Set timeout to 30 seconds
        };

        HttpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", AccessToken);
    }

    public async Task<TResult> GetAsync<TResult>(string requestUri, CancellationToken cancellationToken = default)
    {
        var response = await HttpClient.GetAsync(requestUri, cancellationToken);
        return await ParseResponseAsync<TResult>(response);
    }

    public async Task<TResult> PostAsync<TResult>(string requestUri, object requestBody, CancellationToken cancellationToken = default)
    {
        var content = JsonContent.Create(requestBody);
        var response = await HttpClient.PostAsync(requestUri, content, cancellationToken);
        return await ParseResponseAsync<TResult>(response);
    }

    private async Task<TResult> ParseResponseAsync<TResult>(HttpResponseMessage response)
    {
        response.EnsureSuccessStatusCode();
        var result = await response.Content.ReadAsAsync<TResult>();
        return result;
    }
}
```

2. Inherit from this base class and override the `ParseResponseAsync` method if necessary for specific services:

